L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "끈질긴 것 하나만큼은 인정할 만하군요. 암군이 으스러뜨린 세계의 유일한 생존자답네요."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "しぶとさだけは認めてさしあげましょう。暗君が握りつぶした世界の、唯一の生き残りは伊達ではありませんね。"
L22_1.m_Talk_ENG = "Your tenacity is worth noting. Just like the sole survivor of a world crushed by the Ignorant Monarch."
L22_1.m_Talk_TWN = "頑強這一點倒是值得認可。不愧是唯一在暗君摧毀的世界中活下來的人。"
L22_1.m_Talk_SCN = "顽强这一点倒是值得认可。不愧是唯一在暗君摧毁的世界中活下来的人。"
L22_1.m_Talk_DEU = "Your tenacity is worth noting. Just like the sole survivor of a world crushed by the Ignorant Monarch."
L22_1.m_Talk_FRA = "Your tenacity is worth noting. Just like the sole survivor of a world crushed by the Ignorant Monarch."
