L28_1.m_Face = "UNIT_SERIOUS"
L28_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L28_1.m_Pos = "L"
L28_1.m_Talk_KOREA = "설마 당신의 옛 동료들과 그녀를 겹쳐서 보고 있는 걸까요?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "まさかあなたのかつての仲間と彼女を重ねて見ているのですか？"
L28_1.m_Talk_ENG = "Could it be that you're projecting your old comrades onto her?"
L28_1.m_Talk_TWN = "難道你把她和你的舊同事們重疊在一起了嗎？"
L28_1.m_Talk_SCN = "难道你把她和你的旧同事们重叠在一起了吗？"
L28_1.m_Talk_DEU = "Could it be that you're projecting your old comrades onto her?"
L28_1.m_Talk_FRA = "Could it be that you're projecting your old comrades onto her?"
