L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "따라서 우리가 노엘이라고 믿고 있던 건, 결국 노엘의 허상에 불과했던 거야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "つまり私たちがノエルだと信じていたのは、結局ノエルの虚像に過ぎなかった。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "The Noelle we've been looking at this whole time was just a fake."
L39_1.m_Talk_ENG = L40_1
L40_1 = "因此，我們所相信的洛艾兒，最終不過是洛艾兒的幻影而已。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "因此，我们所相信的诺艾尔，最终不过是诺艾尔的幻影罢了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "The Noelle we've been looking at this whole time was just a fake."
L39_1.m_Talk_DEU = L40_1
L40_1 = "The Noelle we've been looking at this whole time was just a fake."
L39_1.m_Talk_FRA = L40_1
