L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 619
L40_1.m_CutScenStrID = "EP13_ACT4_STAGE4_START"
