L40_1.m_Face = "UNIT_SERIOUS"
L41_1 = "YOOMINA_FENRIR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "R"
L41_1 = "그렇다면 진짜 노엘은 어디선가 여전히 우리를 지켜보고 있지 않을까?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "だったら本当のノエルは、今もなお、どこからか私たちを見守っているんじゃないか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "That means the real Noelle might still be watching us from somewhere."
L40_1.m_Talk_ENG = L41_1
L41_1 = "那麼真正的洛艾兒會不會在某個地方依然注視著我們呢？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "那么真正的诺艾尔会不会在某个地方依然注视着我们呢？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "That means the real Noelle might still be watching us from somewhere."
L40_1.m_Talk_DEU = L41_1
L41_1 = "That means the real Noelle might still be watching us from somewhere."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
