L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "R"
L42_1 = "저 하늘 위에 있는 달에서 말이야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "あの空の上に浮かぶ月、とかね。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Like from the moon above."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我是在說那天上的月亮。"
