L49_1.m_Talk_JPN = L50_1
L50_1 = "That shell, her body, returned to nothing. But her essence, her Divinity, will remain in this world."
L49_1.m_Talk_ENG = L50_1
L50_1 = "軀殼已成虛無，其本質神性將很快駐留於此地。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "躯壳已成虚无，其本质神性将很快驻留于此地。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "That shell, her body, returned to nothing. But her essence, her Divinity, will remain in this world."
