L6_1.m_CharScale = L7_1
L6_1.m_CharScaleTime = 0.01
L7_1 = "아니, 네 표현을 빌리자면 지금, 이 세계조차 또 하나의 각본이 아니었을까?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "いや、あなたの表現を借りて言うなら、今のこの世界もまた一つの脚本だったんじゃない？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Or, using your words, maybe even this entire world was just another script."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不，借用你的說法，現在，這個世界難道不也是另一個劇本嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "不，借用你的说法，现在，这个世界难道不也是另一个剧本吗？"
L6_1.m_Talk_SCN = L7_1
