L48_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L49_1 = "이 극장은 제 완전 기억 능력과 타기리온의 클리파 허수 에너지를 통해 재구성된 공간……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "この劇場は、私の完全記憶能力とタギリオンのクリファ虚数エネルギーによって再構築された空間……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "This space was reconstructed through my perfect memory and Thagirion's Qlipha Imaginary Energy...."
L48_1.m_Talk_ENG = L49_1
L49_1 = "這個劇場是通過我的完全記憶能力和塔基里翁的逆卡巴拉虛數能量重構的空間……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "这个剧场是通过我的完全记忆能力和塔基莱恩的逆卡巴拉虚数能量重构的空间……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "This space was reconstructed through my perfect memory and Thagirion's Qlipha Imaginary Energy...."
L48_1.m_Talk_DEU = L49_1
