L49_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L50_1 = "원래라면 극장의 사용은 최소화하려 했지만, 상황이 상황인 만큼 어쩔 수 없겠죠."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "可能な限り劇場の使用は控えたかったのですが、状況が状況ですので仕方ありませんね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Originally, I had hoped to avoid using the theater, but given the situation, I've changed my mind."
L49_1.m_Talk_ENG = L50_1
L50_1 = "本來是想儘量減少劇場的使用，但情況如此，也沒辦法了。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "本来是想尽量减少剧场的使用，但情况如此，也没办法了。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Originally, I had hoped to avoid using the theater, but given the situation, I've changed my mind."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Originally, I had hoped to avoid using the theater, but given the situation, I've changed my mind."
L49_1.m_Talk_FRA = L50_1
