L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L51_1 = "제게도 당신들처럼 이루고 싶은 게 있으니까요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
