L11_1.m_Pos = "C"
L12_1 = "우리 세계가 어떻게 멸망해 버렸는지, 내일을 빼앗겨 버린 세계의 말로가 어떻게 되는지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "私の世界がどのようにして滅亡したか、明日を奪われた世界がどのような結末を迎えるか。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "How our world fell to ruin, and how a world with its future stolen ends up."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我們的世界是如何毀滅的，被奪走的世界將會走向何方。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "我们的世界是如何毁灭的，被夺走的世界将会走向何方。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "How our world fell to ruin, and how a world with its future stolen ends up."
L11_1.m_Talk_DEU = L12_1
L12_1 = "How our world fell to ruin, and how a world with its future stolen ends up."
L11_1.m_Talk_FRA = L12_1
